UPDATE b_review_ai
SET gmt_modify = now()

    , question = #{question}


    , review_results = #{reviewResults}

WHERE id = #{id}

mapper.select:
SELECT id, gmt_create, gmt_modify, service_order_id, question, admin_user_id, review_results
FROM b_review_ai


        AND service_order_id = #{serviceOrderId}


        AND admin_user_id = #{adminUserId}


ORDER BY gmt_create DESC
LIMIT #{offset}, #{pageSize}

